:root{--paper:#f5f0e7;--ink:#30271f;--rust:#a43d26;--muted:#776a5e;--rule:#d9cfc0;--sand:#e8dfd1}
html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink)}
