.miga-root h1,.miga-root h2,.miga-root h3,.miga-root p{margin:0;color:inherit}.miga-root .elementor-widget-text-editor{font-family:Arial,Helvetica,sans-serif;color:inherit}
.miga-root .elementor-heading-title{font-family:Georgia,'Times New Roman',serif;color:inherit;font-weight:400;line-height:1.04;letter-spacing:-2px}
.miga-root h1.elementor-heading-title{font-size:clamp(64px,7.6vw,110px)}.miga-root h2.elementor-heading-title{font-size:clamp(40px,4.6vw,64px)}.miga-root h3.elementor-heading-title{font-size:24px;letter-spacing:-.5px}
.miga-root em{font-weight:400}.miga-root a{color:inherit;text-decoration:none}.miga-root button,.miga-root input,.miga-root select{font:inherit}.miga-root a:focus-visible,.miga-root button:focus-visible,.miga-root summary:focus-visible{outline:3px solid #cc7a39;outline-offset:6px}
